import React from 'react';
import { Package, Box, Truck } from 'lucide-react';

const KPIHeader = ({ orders }) => {
  const totalBranches = orders.length;
  const totalCbm = orders.reduce((sum, order) => sum + (order.totalCbm || 0), 0).toFixed(2);

  const totalTrucks = orders.reduce((totals, order) => {
    totals.jumbo4m += order.recommendedTrucks?.jumbo4m || 0;
    totals.jumbo += order.recommendedTrucks?.jumbo || 0;
    totals.dabbaba += order.recommendedTrucks?.dabbaba || 0;
    return totals;
  }, { jumbo4m: 0, jumbo: 0, dabbaba: 0 });

  const kpis = [
    {
      title: 'Total Branches',
      value: totalBranches,
      icon: <Package className="w-4 h-4 text-blue-500" />,
      bgColor: 'bg-blue-50/70',
      borderColor: 'border-blue-100',
    },
    {
      title: 'Total Volume (CBM)',
      value: totalCbm,
      icon: <Box className="w-4 h-4 text-purple-500" />,
      bgColor: 'bg-purple-50/70',
      borderColor: 'border-purple-100',
    },
    {
      title: 'Recommended Trucks',
      value: (
        <div className="flex flex-wrap gap-1 text-xs mt-0.5">
          <span className="bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded font-semibold">J4M: {totalTrucks.jumbo4m}</span>
          <span className="bg-pink-100 text-pink-700 px-1.5 py-0.5 rounded font-semibold">Jumbo: {totalTrucks.jumbo}</span>
          <span className="bg-orange-100 text-orange-700 px-1.5 py-0.5 rounded font-semibold">Dabbaba: {totalTrucks.dabbaba}</span>
        </div>
      ),
      icon: <Truck className="w-4 h-4 text-indigo-500" />,
      bgColor: 'bg-indigo-50/70',
      borderColor: 'border-indigo-100',
      isComponent: true
    }
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
      {kpis.map((kpi, index) => (
        <div key={index} className={`rounded-xl p-3 border shadow-xs flex items-center gap-3 ${kpi.bgColor} ${kpi.borderColor}`}>
          <div className="p-2 bg-white rounded-lg shadow-xs flex-shrink-0">
            {kpi.icon}
          </div>
          <div className="min-w-0 flex-1">
            <h3 className="text-slate-500 text-xs font-medium uppercase tracking-wider">{kpi.title}</h3>
            {kpi.isComponent ? (
              kpi.value
            ) : (
              <p className="text-lg font-bold text-slate-800 leading-tight mt-0.5">{kpi.value}</p>
            )}
          </div>
        </div>
      ))}
    </div>
  );
};

export default KPIHeader;
